def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    stripes=[]
    for r,row in enumerate(grid):
        if sum(v != 0 for v in row) < 5:
            continue
        # Fill one-cell gaps inside horizontal stripes.
        for c in range(1,w-1):
            if row[c] == 0 and row[c-1] != 0 and row[c+1] != 0:
                g[r][c] = row[c-1] if row[c-1] == row[c+1] else row[c+1]
        # Collect filled contiguous color segments.
        segs=[]
        c=0
        while c<w:
            if g[r][c]==0:
                c+=1
                continue
            color=g[r][c]
            lo=c
            while c+1<w and g[r][c+1]==color:
                c+=1
            segs.append((lo,c,color))
            c+=1
        stripes.append((r,segs))
    tracks=[c for c in range(w) if any(grid[r][c] for r in range(h-3,h))]
    for c in tracks:
        crossings=[]
        for r,segs in stripes:
            color=next((color for lo,hi,color in segs if lo<=c<=hi),None)
            if color is not None:
                crossings.append((r,color))
        prev=-1
        for r,color in crossings:
            for y in range(prev+1,r):
                g[y][c]=color
            prev=r
    # Extend the bottom marker pair through the blank tail below the last stripe.
    if bars:
        last=max(bars)
        for c in tracks:
            seed=next((r for r in range(h-1,-1,-1) if grid[r][c]),None)
            if seed is not None:
                for r in range(last+1,seed):
                    g[r][c]=grid[seed][c]
    return g

